#
# UART Bootloader for SoC
# Equivalent of the bootloader generated by gen_hex.py
#
# Configures the UART transceiver (16550-compatible @ 0x03000000),
# sends a handshake (bytes 1..4), then receives 8 words (32 bytes)
# via UART, stores them to SRAM starting at 0x1000, and jumps there
# to execute the loaded firmware. On return, enters an infinite loop.
#
# Register usage:
#   t0 (x5)  - UART base address (0x03000000)
#   t3 (x28) - firmware execution address (0x1000)
#   t4 (x29) - firmware store pointer (starts at 0x1000)
#   a0 (x10) - remaining word count
#   t1 (x6)  - general temp / byte counter
#   t2 (x7)  - general temp / loop limit / LSR readback
#   a1 (x11) - received byte (shifted)
#   x30      - accumulated 32-bit word
#   x31      - shift amount (0, 8, 16, 24)
#

    .text
    .globl _start

_start:
    # =========================================================
    # UART_BASE = 0x03000000
    # =========================================================
    lui   t0, 0x03000           # t0 = 0x03000000 (UART base)
    lui   t4, 0x00001           # t4 = 0x00001000 (FW store ptr)
    lui   t3, 0x00001           # t3 = 0x00001000 (FW exec addr)

    # =========================================================
    # 1. Enable Divisor Latch Access (DLAB=1)  LCR = 0x80
    # =========================================================
    addi  t1, x0, 0x80
    sb    t1, 3(t0)             # LCR = 0x80

    # =========================================================
    # 2. Set baud divisor for 115200 @ 100 MHz
    #    DLM = 0x00, DLL = 0x36
    # =========================================================
    addi  t1, x0, 0x00
    sb    t1, 1(t0)             # DLM = 0
    addi  t1, x0, 0x36
    sb    t1, 0(t0)             # DLL = 0x36

    # =========================================================
    # 3. Set line for 8N1 (DLAB=0)  LCR = 0x03
    # =========================================================
    addi  t1, x0, 0x03
    sb    t1, 3(t0)             # LCR = 0x03

    # =========================================================
    # 4. Enable FIFO, clear FIFOs  FCR = 0xC6
    # =========================================================
    addi  t1, x0, 0xC6
    sb    t1, 2(t0)             # FCR = 0xC6

    # =========================================================
    # 5. Word count = 8 (total words to receive)
    # =========================================================
    addi  a0, x0, 8             # a0 = 8

    # =========================================================
    # 6. Handshake: send bytes 1, 2, 3, 4 to signal "ready"
    # =========================================================
    addi  t1, x0, 1             # t1 = 1 (start value)
    addi  t2, x0, 5             # t2 = 5 (loop limit)

handshake_send:
    sb    t1, 0(t0)             # write byte to UART THR
    addi  t1, t1, 1             # t1++
    bge   t2, t1, handshake_send  # while t2 >= t1

    # =========================================================
    # 7. Receive loop: accumulate 4 bytes into a 32-bit word
    # =========================================================
loop_word:
    addi  t1, x0, 4             # byte_counter = 4
    addi  x31, x0, 0            # shift_amount = 0
    addi  x30, x0, 0            # accumulated_word = 0

poll_lsr:
    lb    t2, 12(t0)            # read LSR (offset 0x0C)
    andi  t2, t2, 0x01          # check Data Ready bit
    beq   t2, x0, poll_lsr      # loop until data available

read_byte:
    lbu   a1, 0(t0)             # read RBR (received byte)
    sll   a1, a1, x31           # shift byte to correct position
    add   x30, x30, a1          # accumulate into word
    addi  x31, x31, 8           # next shift = +8
    addi  t1, t1, -1            # byte_counter--
    beq   t1, x0, store_word    # if 4 bytes done -> store
    j     poll_lsr              # else poll for next byte

    # =========================================================
    # 8. Store assembled word to SRAM, advance pointer
    # =========================================================
store_word:
    sw    x30, 0(t4)            # store word at dest ptr
    addi  t4, t4, 4             # dest_ptr += 4
    addi  a0, a0, -1            # word_count--
    beq   a0, x0, execute_fw    # if all 8 words received -> execute
    j     loop_word             # else receive next word

    # =========================================================
    # 9. Jump to loaded firmware at 0x1000
    # =========================================================
execute_fw:
    jalr  ra, t3, 0             # jump to 0x1000, save return in ra
    j     done                  # on return, fall into done

    # =========================================================
    # 10. Infinite loop (halt)
    # =========================================================
done:
    j     done
